package ts

import (
	"cmp"
	"fmt"
	"maps"
	"path"
	"regexp"
	"slices"
	"strings"

	"github.com/hydroan/gst/internal/ggconst"
	"github.com/hydroan/gst/internal/gggen/jsonshape"
	"github.com/hydroan/gst/internal/gst"
)

// This file holds the layout of the output: the file the declarations of each
// package go to, the imports between those files, and the prelude.

// files assembles the output: the prelude, and a file per package with
// declarations, which appear in source order after the imports of the
// packages they refer to, as in
//
//	// Code generated by gst; DO NOT EDIT.
//
//	import type * as $record from "./record.js";
//	import type * as $pkg$notifier from "./pkg/notifier.js";
//
//	/** Sample is a resource kept by the sample service. */
//	export interface Sample {
//	  ...
//	}
func (g *generator) files() []File {
	// The output mirrors the models: a project whose routes exchange no type
	// has nothing to describe, and the prelude alone would describe nothing.
	if len(g.cfg.Roots) == 0 {
		return nil
	}

	byPackage := make(map[string][]*declaration)
	for obj, d := range g.decls {
		if d != nil && d.text != "" {
			byPackage[obj.Pkg().Path()] = append(byPackage[obj.Pkg().Path()], d)
		}
	}

	files := []File{{Path: g.preludeFile, Content: prelude()}}
	owners := map[string]string{g.preludeFile: "the framework prelude"}
	aliases := make(map[string]string)
	for _, pkgPath := range slices.Sorted(maps.Keys(byPackage)) {
		file := g.filePath(pkgPath)
		if owner, taken := owners[file]; taken {
			g.project.Report(jsonshape.Site{Subject: pkgPath}, "the package would be written to %s, which %s takes already; rename the package", file, owner)
			continue
		}
		owners[file] = pkgPath

		decls := byPackage[pkgPath]
		slices.SortFunc(decls, func(a, b *declaration) int {
			return jsonshape.ComparePositions(g.project.FileSet(), a.obj.Pos(), b.obj.Pos())
		})
		imports := make(map[string]bool)
		for _, d := range decls {
			maps.Copy(imports, d.imports)
		}

		var b strings.Builder
		b.WriteString(ggconst.CodeGeneratedComment)
		b.WriteString("\n")
		if len(imports) > 0 {
			b.WriteString("\n")
		}
		for _, imported := range slices.Sorted(maps.Keys(imports)) {
			alias := g.importAlias(imported)
			if other, clash := aliases[alias]; clash && other != imported {
				g.project.Report(jsonshape.Site{Subject: imported}, "the package and %s are both imported as %s; rename one of them", other, alias)
			}
			aliases[alias] = imported
			fmt.Fprintf(&b, "import type * as %s from %s;\n", alias, quoteString(relativeImport(file, g.filePath(imported))))
		}
		for _, d := range decls {
			b.WriteString("\n")
			b.WriteString(d.text)
		}
		files = append(files, File{Path: file, Content: b.String()})
	}
	slices.SortFunc(files, func(a, b File) int { return strings.Compare(a.Path, b.Path) })
	return files
}

// relativePackage returns the output path of a package, extension aside. The
// packages of the root tree sit at the output root, so the model directory is
// not repeated in every path; the root package itself keeps that directory's
// name. The packages of a declared tree sit there the same way. Any other
// package keeps its path relative to the module, which is what tells a reader
// it comes from elsewhere. With the module example.com/app, the root tree
// example.com/app/model and the declared tree example.org/lib/internal/model,
// it returns sample for example.com/app/model/sample, model for
// example.com/app/model, iam/account for
// example.org/lib/internal/model/iam/account, pkg/notifier for
// example.com/app/pkg/notifier, and index for the module root package.
func (g *generator) relativePackage(pkgPath string) string {
	for _, tree := range append([]string{g.cfg.RootPath}, g.cfg.DeclaredTrees...) {
		if tree == "" {
			continue
		}
		if pkgPath == tree {
			return path.Base(tree)
		}
		if rel, inTree := strings.CutPrefix(pkgPath, tree+"/"); inTree {
			return rel
		}
	}
	return cmp.Or(strings.TrimPrefix(strings.TrimPrefix(pkgPath, g.cfg.ModulePath), "/"), "index")
}

// filePath returns the output file of a package.
func (g *generator) filePath(pkgPath string) string {
	return g.relativePackage(pkgPath) + ".ts"
}

// nonIdentifier matches a character an import name cannot hold.
var nonIdentifier = regexp.MustCompile(`[^A-Za-z0-9_]`)

// importAlias names the namespace a file imports a package under: the relative
// package path with its segments joined by $, as in $sample, $iam$account and
// $pkg$http_client for pkg/http-client. Go identifiers never hold $, so the
// name cannot collide with a declaration.
func (g *generator) importAlias(pkgPath string) string {
	segments := strings.Split(g.relativePackage(pkgPath), "/")
	for i, segment := range segments {
		segments[i] = nonIdentifier.ReplaceAllString(segment, "_")
	}
	return "$" + strings.Join(segments, "$")
}

// relativeImport returns the specifier the file at from imports the file at to
// with: ./record.js from sample.ts to record.ts, ../record.js from
// iam/account.ts, and ../../pkg/notifier.js from iam/admin/user.ts to
// pkg/notifier.ts. The .js extension resolves under every TypeScript module
// resolution mode, including the node modes, which require an extension.
func relativeImport(from, to string) string {
	var fromDirs []string
	if dir := path.Dir(from); dir != "." {
		fromDirs = strings.Split(dir, "/")
	}
	toParts := strings.Split(strings.TrimSuffix(to, ".ts"), "/")
	common := 0
	for common < len(fromDirs) && common < len(toParts)-1 && fromDirs[common] == toParts[common] {
		common++
	}
	parts := make([]string, 0, len(fromDirs)+len(toParts))
	for range fromDirs[common:] {
		parts = append(parts, "..")
	}
	parts = append(parts, toParts[common:]...)
	specifier := strings.Join(parts, "/") + ".js"
	if !strings.HasPrefix(specifier, "../") {
		specifier = "./" + specifier
	}
	return specifier
}

// nonFileName matches a character the prelude file name cannot hold.
var nonFileName = regexp.MustCompile(`[^A-Za-z0-9_-]`)

// preludeFileName returns the file the prelude goes to: the application name,
// or the framework name when the project configured none. Whatever a file name
// and an import specifier cannot hold is replaced, so every configured name
// yields a file a frontend can copy and import: shop.ts for shop,
// Sample_Shop___v2.ts for "Sample Shop / v2", and gst.ts for none.
func preludeFileName(appName string) string {
	return cmp.Or(strings.Trim(nonFileName.ReplaceAllString(appName, "_"), "_-"), gst.FrameworkName) + ".ts"
}

// prelude declares the JSON the framework wraps around the project's types:
// the envelopes internal/response writes, one for a successful response and
// one for a failed one, and the list data and batch request bodies of the
// default actions in internal/controller.
func prelude() string {
	return ggconst.CodeGeneratedComment + `

/**
 * Envelope is the JSON body of a successful response: 200 with the data of
 * the route. The status tells a success from a failure, whose body is an
 * ErrorEnvelope.
 */
export interface Envelope<T> {
  data: T;
  msg: string;
  trace_id: string;
}

/**
 * ErrorEnvelope is the JSON body of a failed response: its 4xx or 5xx status
 * with the error message, data null and, when the failure carries details,
 * error. A failure carrying no details has no error member.
 */
export interface ErrorEnvelope {
  data: null;
  msg: string;
  trace_id: string;
  error?: ErrorDetails;
}

/**
 * ErrorDetails is what a failed request carries beyond its message: the
 * fields the request was refused on, when the failure names any.
 */
export interface ErrorDetails {
  field_violations?: FieldViolation[];
}

/**
 * FieldViolation is one field a request was refused on: the field by its
 * JSON key path, address.city or items[1].name, and the description of what
 * it failed.
 */
export interface FieldViolation {
  field: string;
  description: string;
}

/**
 * ListResult is the data of the default List action: total counts the
 * records the query matches, 0 under cursor pagination, and has_more tells
 * whether records lie past the page, before it when the cursor is read
 * backward, after it otherwise.
 */
export interface ListResult<T> {
  items: T[];
  total: number;
  has_more: boolean;
}

/** ItemsPayload is the request body of the default batch create, update and patch actions. */
export interface ItemsPayload<T> {
  items: T[];
}

/** IDsPayload is the request body of the default batch delete action. */
export interface IDsPayload {
  ids: string[];
}
`
}
